resource "aws_iam_role_policy" "kb_narrow" {
  role   = aws_iam_role.kb_service_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["bedrock:Retrieve", "bedrock:RetrieveAndGenerate"]
        Resource = [aws_bedrockagent_knowledge_base.example.arn]  # scoped to this KB
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:ListBucket"]
        Resource = [aws_s3_bucket.kb_data.arn, "${aws_s3_bucket.kb_data.arn}/*"]
      }
    ]
  })
}
